code.cpp:
class Solution {
public:
    vector<string> wordSubsets(vector<string>& words1, vector<string>& words2) {
        int maxFreq[26] = {0};

        for (const string& b : words2) {
            int freq[26] = {0};
            for (char c : b) {
                freq[c - 'a']++;
            }
            for (int i = 0; i < 26; i++) {
                if (freq[i] > maxFreq[i]) {
                    maxFreq[i] = freq[i];
                }
            }
        }

        vector<string> result;

        for (const string& a : words1) {
            int freq[26] = {0};
            for (char c : a) {
                freq[c - 'a']++;
            }
            bool universal = true;
            for (int i = 0; i < 26; i++) {
                if (freq[i] < maxFreq[i]) {
                    universal = false;
                    break;
                }
            }
            if (universal) {
                result.push_back(a);
            }
        }

        return result;
    }
};
